/// Built-in Game of Life rules, mirroring `builtinGol`.
pub struct GolRule {
    pub name: &'static str,
    /// bits 0..8 = stay-if-N neighbours, bits 9..17 = begin-if-N, bits 17..20 = states-2.
    pub ruleset: u32,
    pub states: u8,
    pub colour1: u32,
    pub colour2: u32,
    pub description: &'static str,
}

